<template>
 <section class="management-page lost-found-page">
  <span class="page-kicker">FLAT COMMUNITY</span>
  <div class="page-heading"><div><h1 class="page-title">Notices</h1><p class="lead">Reports are visible only to members of the selected flat.</p></div><button class="button button-secondary" :disabled="loading" @click="load">Refresh</button></div>
  <StatusMessage :message="error" error/><StatusMessage :message="success"/><section v-if="can('COMMUNITY_NOTICE_CREATE')" class="panel community-create"><h2 class="section-title">Create a community notice</h2><p class="muted">All notices go to the administrator for review before publication.</p><form class="lost-found-form" @submit.prevent="submitCommunityNotice"><Input name="communityTitle" label="Title" v-model="communityDraft.title" maxlength="160" required/><label class="field">Audience<small class="field-hint">Choose who can see this notice.</small><select v-model="communityDraft.audienceScope" class="select-input"><option v-if="can('COMMUNITY_NOTICE_ADMIN')" value="SOCIETY">Whole society</option><option value="FLATS">Selected flats</option><option v-if="!can('COMMUNITY_NOTICE_ADMIN')" value="ADMIN_ONLY">Administrator only</option></select></label><label v-if="communityDraft.audienceScope==='FLATS'" class="field field-wide">Target flats<small class="field-hint">Select the flats that should receive this notice.</small><select v-model="communityDraft.flatIds" class="select-input" multiple required><option v-for="flat in noticeFlatOptions" :key="flat.flatId" :value="flat.flatId">{{ flat.flatNumber }}</option></select><small>Hold Ctrl to select multiple flats.</small></label><label class="field field-wide">Notice details<textarea v-model="communityDraft.message" class="text-input" maxlength="4000" rows="4" required></textarea></label><div class="field-wide form-actions"><button class="button" :disabled="communitySaving">{{ communitySaving?'Submitting…':'Submit for review' }}</button></div></form></section><section v-if="can('COMMUNITY_NOTICE_ADMIN')" class="panel admin-panel"><div class="section-heading"><div><span class="page-kicker">SOCIETY OFFICE</span><h2 class="section-title">Community notice review</h2><p class="muted">Review the content and audience before publishing.</p></div><button class="button button-secondary button-small" @click="loadCommunityAdmin">Refresh queue</button></div><p v-if="!communityAdminQueue.length" class="muted">No notices awaiting review.</p><article v-for="entry in communityAdminQueue" :key="entry.notice.id" class="admin-report"><div class="admin-report-main"><strong>{{ entry.notice.title }} · Submitted by {{ entry.createdBy }}</strong><span class="status">{{ statusLabel(entry.notice.status) }}</span></div><p>{{ entry.notice.message }}</p><div class="admin-actions"><label class="field">Audience<small class="field-hint">Choose who can see this notice.</small><select v-model="communityAudiences[entry.notice.id].scope" class="select-input"><option value="SOCIETY">Whole society</option><option value="FLATS">Selected flats</option><option value="ADMIN_ONLY">Administrator only</option></select></label><label v-if="communityAudiences[entry.notice.id].scope==='FLATS'" class="field">Target flats<small class="field-hint">Select the flats that should receive this notice.</small><select v-model="communityAudiences[entry.notice.id].flatIds" class="select-input" multiple><option v-for="flat in noticeFlatOptions" :key="flat.flatId" :value="flat.flatId">{{ flat.flatNumber }}</option></select></label><button class="button button-secondary button-small" @click="saveCommunityAudience(entry)">Save audience</button><button v-if="entry.notice.status==='SUBMITTED'" class="button button-small" @click="setCommunityStatus(entry,'UNDER_REVIEW')">Start review</button><button v-if="entry.notice.status==='UNDER_REVIEW'" class="button button-small" @click="setCommunityStatus(entry,'PUBLISHED')">Approve &amp; publish</button><button class="button button-danger button-small" @click="setCommunityStatus(entry,'REJECTED')">Reject</button></div></article></section><section class="panel"><div class="section-heading"><div><h2 class="section-title">Community notices</h2><p class="muted">Society-wide notices and notices for your active flats.</p></div><span class="notice-count">{{ communityBoard.length }}</span></div><p v-if="!communityBoard.length" class="empty-board">No community notices yet.</p><div v-else class="notice-cards"><article v-for="item in communityBoard" :id="'notice-'+item.id" :key="item.id" class="notice-card" tabindex="-1"><div class="notice-card-heading"><div><span class="notice-type found">Community notice</span><h3>{{ item.title }}</h3></div><span class="status">{{ statusLabel(item.status) }}</span></div><p class="notice-description">{{ item.message }}</p><small class="muted">{{ date(item.createdAt) }}</small></article></div></section>
  
  <div class="lost-found-columns">
   <section class="panel"><h2 class="section-title">Report an item</h2><p class="muted">Reports are reviewed by the society office before publication.</p>
    <form class="lost-found-form" @submit.prevent="submitReport">
     <label v-if="flatOptions.length!==1||can('LOST_FOUND_ADMIN')" class="field field-wide">Flat<small class="field-hint">Choose the flat for this record.</small><select v-model="draft.flatId" class="select-input" required><option value="" disabled>Select the flat</option><option v-for="flat in flatOptions" :key="flat.flatId" :value="flat.flatId">{{ flat.label }}</option></select></label>
     <label class="field">Report type<small class="field-hint">Choose whether the item was lost or found.</small><select v-model="draft.reportType" class="select-input"><option value="LOST">Lost</option><option value="FOUND">Found</option></select></label>
     <label class="field">Item<small class="field-hint">Choose the closest item category.</small><select v-model="draft.itemType" class="select-input"><option v-for="item in itemOptions" :key="item" :value="item">{{ item==='OTHER'?'Other':item }}</option></select></label>
     <Input v-if="draft.itemType==='OTHER'" name="itemOther" label="Describe the item" v-model="draft.itemOther" maxlength="120" required/>
     <Input name="itemLocation" label="Location" v-model="draft.location" maxlength="240" required/>
     <Input name="itemDateTime" label="Date and time" v-model="draft.occurredAt" type="datetime-local" required/>
     <label class="field field-wide">Description<textarea v-model="draft.description" class="text-input" maxlength="2000" rows="3" required></textarea></label>
     <label class="field">Contact preference<small class="field-hint">Choose how the owner should be contacted.</small><select v-model="draft.contactPreference" class="select-input"><option value="SOCIETY_OFFICE">Through the society office</option><option value="OTHER">Other</option></select></label>
     <Input v-if="draft.contactPreference==='OTHER'" name="contactOther" label="Contact details or preference" v-model="draft.contactOther" maxlength="240" required/>
     <label class="field field-wide">Optional photo · JPEG, PNG, or WebP, up to 5 MB<input class="file-input" type="file" accept="image/jpeg,image/png,image/webp" @change="selectPhoto"></label>
     <div class="field-wide form-actions"><button class="button" :disabled="saving">{{ saving?'Submitting…':'Submit for review' }}</button><button type="button" class="button button-secondary" @click="resetForm">Clear</button></div>
    </form>
   </section>
   <section class="panel"><div class="section-heading"><div><h2 class="section-title">Notice board</h2><p class="muted">Only approved notices for your active flat memberships appear here.</p></div><span class="notice-count">{{ board.length }}</span></div>
    <p v-if="loading" class="muted">Loading…</p><p v-else-if="!board.length" class="empty-board">No open notices yet.</p>
    <div v-else class="notice-cards"><article v-for="item in board" :id="'notice-'+item.id" :key="item.id" class="notice-card" tabindex="-1">
     <div class="notice-card-heading"><div><span class="notice-type" :class="item.reportType.toLowerCase()">{{ item.reportType==='FOUND'?'Found':'Lost' }}</span><h3>{{ item.itemType==='OTHER'?item.itemOther:item.itemType }}</h3></div><span class="status">{{ statusLabel(item.status) }}</span></div>
     <p class="muted">{{ item.location }} · {{ date(item.occurredAt) }}</p><p class="notice-description">{{ item.description }}</p><img v-if="item.photoUrl" class="notice-photo" :src="item.photoUrl" alt="Photo attached to this notice">
     <form v-if="can('LOST_FOUND_REPORT')&&['PUBLISHED','CLAIM_RECEIVED'].includes(item.status)" class="claim-form" @submit.prevent="submitClaim(item)"><label class="field">Claim this item · add an identifying detail<textarea v-model="claimText[item.id]" class="text-input" maxlength="2000" rows="2" required></textarea></label><button class="button button-small" :disabled="busyClaim===item.id">Claim item</button></form>
    </article></div>
   </section>
  </div>
  <section v-if="can('LOST_FOUND_ADMIN')" class="panel admin-panel"><div class="section-heading"><div><span class="page-kicker">SOCIETY OFFICE</span><h2 class="section-title">Report review</h2><p class="muted">Reporter and claimant details are visible only here.</p></div><button class="button button-secondary button-small" @click="loadAdmin">Refresh queue</button></div>
   <p v-if="adminLoading" class="muted">Loading review queue…</p><p v-else-if="!adminReports.length" class="muted">No reports to review.</p>
   <article v-for="r in adminReports" :key="r.notice.id" class="admin-report"><div class="admin-report-main"><div><strong>{{ r.notice.reportType }} · {{ r.notice.itemType==='OTHER'?r.notice.itemOther:r.notice.itemType }}</strong><span class="muted">{{ r.notice.location }} · {{ date(r.notice.occurredAt) }}</span><span class="muted">Reporter account: {{ r.reporterId }}</span><span class="muted">Contact: {{ r.contactOther||'Through the society office' }}</span></div><span class="status">{{ statusLabel(r.notice.status) }}</span></div>
    <p>{{ r.notice.description }}</p><div v-if="!r.notice.flatId" class="admin-actions"><label class="field">Assign legacy notice to flat<small class="field-hint">Choose an option.</small><select v-model="flatAssignments[r.notice.id]" class="select-input"><option value="" disabled>Select flat</option><option v-for="flat in flatOptions" :key="flat.flatId" :value="flat.flatId">{{ flat.label }}</option></select></label><button class="button button-small" :disabled="!flatAssignments[r.notice.id]" @click="assignFlat(r)">Assign flat</button></div><img v-if="r.notice.photoUrl" class="notice-photo" :src="r.notice.photoUrl" alt="Report photo for admin review">
    <div class="admin-actions"><button v-if="r.notice.status==='SUBMITTED'" class="button button-small" @click="setStatus(r,'UNDER_REVIEW')">Start review</button><button v-if="r.notice.status==='UNDER_REVIEW'" class="button button-small" @click="setStatus(r,'PUBLISHED')">Publish</button><button v-if="['SUBMITTED','UNDER_REVIEW'].includes(r.notice.status)" class="button button-danger button-small" @click="setStatus(r,'REJECTED')">Reject</button><button v-if="['PUBLISHED','CLAIM_RECEIVED'].includes(r.notice.status)" class="button button-small" @click="setStatus(r,'RESOLVED')">Resolve</button><button v-if="['PUBLISHED','CLAIM_RECEIVED'].includes(r.notice.status)" class="button button-secondary button-small" @click="setStatus(r,'CLOSED_UNCLAIMED')">Close unclaimed</button><button v-if="['PUBLISHED','CLAIM_RECEIVED'].includes(r.notice.status)" class="link-button" @click="showClaims(r.notice.id)">Review claims</button></div>
    <div v-if="claimsByReport[r.notice.id]" class="claims-list"><p v-if="!claimsByReport[r.notice.id].length" class="muted">No claims yet.</p><div v-for="claim in claimsByReport[r.notice.id]" :key="claim.id" class="claim-row"><div><strong>Claimant account: {{ claim.claimantId }}</strong><p>{{ claim.identifyingDetails }}</p><small>{{ date(claim.createdAt) }} · {{ claim.status }}</small></div><div v-if="claim.status==='SUBMITTED'" class="claim-actions"><button class="button button-small" @click="decideClaim(r.notice.id,claim.id,'ACCEPTED')">Accept</button><button class="button button-danger button-small" @click="decideClaim(r.notice.id,claim.id,'REJECTED')">Reject</button></div></div></div>
   </article>
  </section>
 </section>
</template>
<script>
import {api,errorMessage} from '../services/api';
import access from '../util/access-mixin';
import Input from '../components/forms/Input.vue';
import StatusMessage from '../components/StatusMessage.vue';
const communityBlank=()=>({title:'',message:'',audienceScope:'ADMIN_ONLY',flatIds:[]});
const blank=()=>({flatId:'',reportType:'FOUND',itemType:'KEYS',itemOther:'',location:'',occurredAt:'',description:'',contactPreference:'SOCIETY_OFFICE',contactOther:''});
export default {
 name:'LostFound',mixins:[access],components:{Input,StatusMessage},
 data(){return {draft:blank(),communityDraft:communityBlank(),communityBoard:[],noticeFlatOptions:[],communityAdminQueue:[],communityAudiences:{},communityAdminLoading:false,communitySaving:false,flatOptions:[],flatAssignments:{},itemOptions:['KEYS','PHONE','WALLET','BAG','CLOTHING','OTHER'],photo:null,board:[],notifications:[],adminReports:[],claimsByReport:{},claimText:{},loading:false,adminLoading:false,saving:false,busyClaim:null,error:'',success:''};},
 mounted(){if(this.can('COMMUNITY_NOTICE_ADMIN'))this.communityDraft.audienceScope='SOCIETY';this.load();this.loadFlatOptions();this.loadCommunityData();if(this.can('LOST_FOUND_ADMIN'))this.loadAdmin();},
 methods:{
  async loadCommunityData(){try{this.communityBoard=await api.noticeBoard();}catch(e){this.error=errorMessage(e);}if(this.can('COMMUNITY_NOTICE_CREATE'))try{this.noticeFlatOptions=await api.noticeFlatOptions();}catch(e){this.error=errorMessage(e);}if(this.can('COMMUNITY_NOTICE_ADMIN'))await this.loadCommunityAdmin();},
  async loadCommunityAdmin(){this.communityAdminLoading=true;try{this.communityAdminQueue=await api.noticeReviewQueue();const next={...this.communityAudiences};for(const entry of this.communityAdminQueue){if(!next[entry.notice.id])next[entry.notice.id]={scope:entry.notice.audienceScope,flatIds:[...(entry.flatIds||[])]};}this.communityAudiences=next;}catch(e){this.error=errorMessage(e);}finally{this.communityAdminLoading=false;}},
  async submitCommunityNotice(){this.communitySaving=true;this.error='';try{await api.createNotice({...this.communityDraft,flatIds:this.communityDraft.audienceScope==='FLATS'?this.communityDraft.flatIds:[]});this.communityDraft=communityBlank();if(this.can('COMMUNITY_NOTICE_ADMIN'))this.communityDraft.audienceScope='SOCIETY';this.success='Your notice was submitted for administrator review.';await this.loadCommunityData();}catch(e){this.error=errorMessage(e);}finally{this.communitySaving=false;}},
  async saveCommunityAudience(entry){try{const a=this.communityAudiences[entry.notice.id];await api.changeNoticeAudience(entry.notice.id,{audienceScope:a.scope,flatIds:a.scope==='FLATS'?a.flatIds:[]});this.success='Notice audience updated.';await this.loadCommunityAdmin();}catch(e){this.error=errorMessage(e);}},
  async setCommunityStatus(entry,status){try{await api.changeNoticeStatus(entry.notice.id,status);this.success=status==='PUBLISHED'?'Notice approved and published.':'Notice review status updated.';await Promise.all([this.loadCommunityData(),this.loadCommunityAdmin()]);}catch(e){this.error=errorMessage(e);}},
  async load(){this.loading=true;this.error='';try{const [board,notifications]=await Promise.all([api.lostFoundBoard(),api.lostFoundNotifications()]);this.board=board;this.notifications=notifications;}catch(e){this.error=errorMessage(e);}finally{this.loading=false;}},
  async loadFlatOptions(){try{const ids=(this.$store.state.session.user&&this.$store.state.session.user.flatIds)||[];let flats;if(this.can('LOST_FOUND_ADMIN')){const result=await api.page('flats',0,{size:100});flats=result.content||result.items||[];}else{flats=await Promise.all(ids.map(id=>api.flatLabel(id)));}this.flatOptions=flats.map(f=>({flatId:f.flatId||f.id,label:f.flatNumber||f.number||f.flatId||f.id})).filter(f=>f.flatId);if(this.flatOptions.length===1)this.draft.flatId=this.flatOptions[0].flatId;}catch(e){this.error='Could not load your flats: '+errorMessage(e);}},
  flatLabel(id){const flat=this.flatOptions.find(f=>f.flatId===id);return flat?flat.label:(id||'Not assigned');},
  async loadAdmin(){this.adminLoading=true;try{this.adminReports=await api.lostFoundAdminReports();this.flatAssignments={...this.flatAssignments,...Object.fromEntries(this.adminReports.filter(r=>!r.notice.flatId).map(r=>[r.notice.id,'']))};}catch(e){this.error=errorMessage(e);}finally{this.adminLoading=false;}},
  async assignFlat(report){const flatId=this.flatAssignments[report.notice.id];if(!flatId)return;try{await api.assignLostFoundFlat(report.notice.id,flatId);this.success='Notice assigned to the selected flat.';await Promise.all([this.load(),this.loadAdmin()]);}catch(e){this.error=errorMessage(e);}},
  selectPhoto(e){const f=e.target.files&&e.target.files[0];if(!f){this.photo=null;return;}if(f.size>5*1024*1024||!['image/jpeg','image/png','image/webp'].includes(f.type)){this.error='Choose a JPEG, PNG, or WebP image under 5 MB.';e.target.value='';this.photo=null;return;}this.error='';this.photo=f;},
  async submitReport(){this.saving=true;this.error='';this.success='';try{const body={...this.draft,occurredAt:new Date(this.draft.occurredAt).toISOString()};const report=await api.createLostFoundReport(body);if(this.photo){try{await api.uploadLostFoundPhoto(report.id,this.photo);}catch(e){this.error='Report submitted, but photo upload failed: '+errorMessage(e);this.resetForm();await this.load();return;}}this.success='Your report was submitted for society office review.';this.resetForm();await this.load();if(this.can('LOST_FOUND_ADMIN'))await this.loadAdmin();}catch(e){this.error=errorMessage(e);}finally{this.saving=false;}},
  resetForm(){this.draft=blank();this.photo=null;const input=this.$el.querySelector('input[type=file]');if(input)input.value='';},
  async submitClaim(item){this.busyClaim=item.id;this.error='';try{await api.submitLostFoundClaim(item.id,(this.claimText[item.id]||'').trim());this.claimText={...this.claimText,[item.id]:''};this.success='Your claim was sent to the society office.';await this.load();}catch(e){this.error=errorMessage(e);}finally{this.busyClaim=null;}},
  async setStatus(r,status){this.error='';try{await api.changeLostFoundStatus(r.notice.id,status);this.success='Report status updated.';await Promise.all([this.load(),this.loadAdmin()]);}catch(e){this.error=errorMessage(e);}},
  async showClaims(id){try{this.claimsByReport={...this.claimsByReport,[id]:await api.lostFoundClaims(id)};}catch(e){this.error=errorMessage(e);}},
  async decideClaim(id,claimId,status){try{await api.decideLostFoundClaim(id,claimId,status);await this.showClaims(id);this.success='Claim decision saved.';}catch(e){this.error=errorMessage(e);}},
  eventLabel(t){return ({LostFoundReportPublished:'A notice was published',LostFoundClaimSubmitted:'A claim was submitted',LostFoundReportResolved:'A report was resolved'})[t]||'Lost & Found update';},
  statusLabel(s){return ({SUBMITTED:'Submitted',UNDER_REVIEW:'Under review',PUBLISHED:'Published',CLAIM_RECEIVED:'Claim received',RESOLVED:'Resolved',REJECTED:'Rejected',EXPIRED:'Expired',CLOSED_UNCLAIMED:'Closed · unclaimed'})[s]||s;},
  date(v){if(!v)return '';const d=new Date(v);return Number.isNaN(d.getTime())?'':d.toLocaleString();},
  focusNotice(id){const e=document.getElementById('notice-'+id);if(e){e.scrollIntoView({behavior:'smooth',block:'center'});e.focus({preventScroll:true});}}
 }
};
</script>
<style scoped>
.lost-found-page{display:grid;gap:20px}.lost-found-columns{display:grid;grid-template-columns:minmax(280px,.85fr) minmax(0,1.15fr);gap:20px;align-items:start}.lost-found-page .panel{padding:22px}.lost-found-form{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:15px;margin-top:18px}.field{display:grid;gap:7px;font-size:13px;font-weight:650;color:var(--ink)}.field-wide{grid-column:1/-1}.form-actions,.admin-actions,.claim-actions{display:flex;flex-wrap:wrap;gap:9px;align-items:center}.notice-count{display:grid;place-items:center;min-width:30px;height:30px;border-radius:50%;background:#e5f3ec;color:#176b50;font-weight:700}.notification-list{list-style:none;padding:0;margin:8px 0 0}.notification-list li{display:flex;gap:12px;align-items:center;border-top:1px solid var(--line);padding:12px 0}.notification-list strong{flex:1}.notification-list small{color:var(--muted)}.notice-cards{display:grid;gap:14px;margin-top:18px}.notice-card,.admin-report{border:1px solid var(--line);border-radius:14px;padding:17px;background:#fff;scroll-margin:100px}.notice-card:focus{outline:3px solid var(--focus-ring)}.notice-card-heading,.admin-report-main{display:flex;justify-content:space-between;gap:14px;align-items:flex-start}.notice-card h3{margin:7px 0 0}.notice-type{display:inline-flex;border-radius:999px;padding:3px 10px;font-size:11px;font-weight:750;background:#f2eaf8;color:#68478b}.notice-type.found{background:#e5f3ec;color:#176b50}.notice-description{color:var(--muted);white-space:pre-wrap;overflow-wrap:anywhere}.notice-photo{display:block;width:min(100%,420px);max-height:280px;object-fit:contain;object-position:left center;border-radius:10px;background:#f4f2ef;margin:12px 0}.claim-form{display:grid;gap:10px;border-top:1px solid var(--line);padding-top:14px;margin-top:14px}.empty-board{padding:35px 12px;text-align:center;color:var(--muted)}.admin-panel{display:grid;gap:12px;margin-top:20px}.admin-report{display:grid;gap:12px}.admin-report-main>div{display:grid;gap:5px}.claims-list{border-top:1px solid var(--line);padding-top:10px}.claim-row{display:flex;justify-content:space-between;gap:12px;padding:12px 0;border-top:1px solid #edf0ed}.claim-row p{margin:5px 0;white-space:pre-wrap}.muted,.empty-board{color:var(--muted)}
@media(max-width:900px){.lost-found-columns{grid-template-columns:1fr}}@media(max-width:560px){.lost-found-page .panel{padding:16px}.lost-found-form{grid-template-columns:1fr}.field-wide{grid-column:auto}.notice-card-heading,.admin-report-main{flex-direction:column}.claim-row{flex-direction:column}}
</style>
